#!/usr/bin/env bash
# Prints the Homebrew formula for a codesynapse release, for the tap
# astrona-io/homebrew-tap (Formula/codesynapse.rb). Used by release.yml after
# the GitHub release is published:
#
#   .github/scripts/homebrew-formula.sh v0.3.0 dist/SHA256SUMS > codesynapse.rb
#
# The formula installs the bare per-platform binaries from the release,
# pinned to the SHA-256 values in SHA256SUMS.
set -euo pipefail

tag="${1:?usage: homebrew-formula.sh <tag> <SHA256SUMS>}"
sums="${2:?usage: homebrew-formula.sh <tag> <SHA256SUMS>}"

if [[ ! "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  echo "homebrew-formula.sh: '$tag' isn't a release tag (vX.Y.Z)" >&2
  exit 1
fi

sha() {
  local s
  s=$(awk -v f="$1" '$2 == f || $2 == "*" f { print $1 }' "$sums")
  if [[ ! "$s" =~ ^[0-9a-f]{64}$ ]]; then
    echo "homebrew-formula.sh: no SHA-256 for $1 in $sums" >&2
    exit 1
  fi
  echo "$s"
}

base="https://github.com/astrona-io/codesynapse/releases/download/${tag}"
darwin_arm64=$(sha codesynapse-darwin-arm64)
darwin_amd64=$(sha codesynapse-darwin-amd64)
linux_arm64=$(sha codesynapse-linux-arm64)
linux_amd64=$(sha codesynapse-linux-amd64)

cat <<RUBY
# Generated by codesynapse's release workflow (.github/scripts/homebrew-formula.sh)
# for ${tag} — don't edit by hand, the next release overwrites it.
class Codesynapse < Formula
  desc "Code graph for review and AI assistants, with the Claude Code MCP bridge"
  homepage "https://github.com/astrona-io/codesynapse"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "${base}/codesynapse-darwin-arm64"
      sha256 "${darwin_arm64}"
    end
    on_intel do
      url "${base}/codesynapse-darwin-amd64"
      sha256 "${darwin_amd64}"
    end
  end

  on_linux do
    on_arm do
      url "${base}/codesynapse-linux-arm64"
      sha256 "${linux_arm64}"
    end
    on_intel do
      url "${base}/codesynapse-linux-amd64"
      sha256 "${linux_amd64}"
    end
  end

  def install
    # A bare download isn't executable yet, and codesynapse runs below to
    # generate its completions.
    binary = Dir["codesynapse-*"].first
    chmod 0755, binary
    bin.install binary => "codesynapse"
    generate_completions_from_executable(bin/"codesynapse", "completion")
  end

  def caveats
    <<~EOS
      Connect Claude Code with a personal key (Settings → API keys in the dashboard):
        CODESYNAPSE_MCP_TOKEN=csk_... codesynapse mcp install --only claude
      then open a new chat. The bridge follows \`brew upgrade codesynapse\`.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/codesynapse --version")
    assert_match "__start_codesynapse", (bash_completion/"codesynapse").read
    # The bridge refuses to start without a chat ID instead of inventing one.
    assert_match "no chat session", shell_output("#{bin}/codesynapse mcp bridge 2>&1", 1)
  end
end
RUBY
